SF = " Edizione con simboli PCS e formato sfogliafacile® (pagine sagomate, facili da sfogliare): per chi ha difficoltà di lettura o di motricità fine e per chi non parla italiano come prima lingua."
def fiaba(txt, pesc=True):
    return (19.0, txt + SF + (" Disponibile anche nel formato Pesciolini a € 12,90." if pesc else ""))
